window.REPORT_PRELOAD_CACHE["XRX.html"] = {"version":"4b4db1c02b057c903cdea9b93ab6fe5bc1113206dd9b1f8a32490d73f98b79aa","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>施乐 Xerox Holdings Corporation (NASDAQ: XRX) 深度研究报告：2026Q3业绩重组、股息暂停与债务优化转型</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n xeroxred: {\n 300: '#FCA5A5',\n 400: '#F87171',\n 500: '#EF4444',\n 600: '#DC2626',\n 700: '#B91C1C',\n },\n xeroxblue: {\n 400: '#60A5FA',\n 500: '#3B82F6',\n 600: '#2563EB',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(239, 68, 68, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #EF4444;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-xeroxred-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-xeroxred-600 via-xeroxred-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-xeroxred-500 to-xeroxblue-500 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n XRX\n </div>\n <div>\n <div class=\"text-[11px] text-xeroxred-400 font-semibold tracking-wider uppercase\">NASDAQ: XRX · Print & Digital Solutions</div>\n <div class=\"text-sm font-bold leading-tight\">施乐 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">XRX 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务架构与Q3财报拆解</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与战略转型</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 办公与打印同行横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与债务复利推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球办公与打印技术研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / SEC 10-Q)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-xeroxred-500 via-xeroxred-600 to-xeroxblue-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-xeroxred-500/25\">\n XRX\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-xeroxred-400 bg-xeroxred-500/15 px-2 py-0.5 rounded\">NASDAQ: XRX</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">施乐深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球打印与数字化解决方案先驱 · 2026Q3 利润率提升、股息暂停与债务优化重组\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$0.91 <span class=\"text-slate-400 text-[10px]\">($0.91-$3.78)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">Q3 2026 营收</span>\n <span class=\"font-mono font-bold text-emerald-400\">$18.7 亿 <span class=\"text-slate-400\">(-4.7% YoY)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">调整后运营利润率</span>\n <span class=\"font-mono font-bold text-xeroxred-400\">6.6% (+330 bps)</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-xeroxred-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构与Q3财报拆解</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与战略转型</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>办公与打印同行横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与债务复利推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-xeroxred-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-xeroxred-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-xeroxred-500 to-xeroxred-600 hover:from-xeroxred-600 hover:to-xeroxred-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-xeroxred-500/15 text-xeroxred-700 dark:text-xeroxred-300 font-bold border border-xeroxred-500/30\">评级：审慎重组 / 利润率改善但面临现金流与债务考验</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q3 业绩发布、股息暂停与债务优化期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NASDAQ: XRX</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#EF4444 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-xeroxred-500/20 border border-xeroxred-400/40 text-xeroxred-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-xeroxred-400 animate-pulse\"></span>\n <span>CORE THESIS · Q3 调整后运营利润率飙升至 6.6%（+330 bps） × 暂停股息以保护现金 × 债务再融资与资产置换推进</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 施乐 Xerox Holdings Corporation (NASDAQ: XRX) 深度研究报告：2026Q3业绩重组、股息暂停与债务优化转型\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 施乐（Xerox）公布了 <strong class=\"text-white\">2026 财年第三季度财报</strong>：受行业结构性顺风及成本精简推动，单季<strong class=\"text-xeroxred-300\">调整后运营利润率翻倍至 6.6%（同比大幅提升 330 个基点）</strong>，调整后每股收益（EPS）达 $0.02，超越市场共识。\n 然而，受累于宏观逆风、较高的输入成本及中端打印设备需求下滑，Q3 总营收录得 <strong class=\"text-white\">$18.7 亿美元（同比下降 4.7%）</strong>。为了应对近期的现金流压降与债务到期压力，公司宣布<strong class=\"text-xeroxred-300\">暂停普通股及优先股股息</strong>，下调全年自由现金流指引至 $5,000–$10,000 万美元，并积极执行债务置换（如将 $1.74 亿 2028 年到期票据延期至 2030 年）。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">调整后运营利润率翻倍</div>\n <div class=\"text-white font-semibold\">Q3 调整后运营利润率达 6.6%（同比提升 330 bps），运营利润大增至 $1.24 亿美元</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">股息暂停与现金保全</div>\n <div class=\"text-xeroxred-300 font-semibold\">CEO Louie Pastor 宣布暂停普通与优先股股息，全力削减成本、优化资产负债表与偿还债务</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">债务期限延长与置换</div>\n <div class=\"text-emerald-400 font-semibold\">成功完成 $1.74亿 2028年高级票据向 2030 年担保票据与股权的置换交易</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>参考股价与市值</span>\n <span class=\"p-1.5 rounded-lg bg-xeroxred-500/15 text-xeroxred-600 dark:text-xeroxred-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$1.21M</span>\n <span class=\"text-xs font-bold text-rose-600 dark:text-rose-400 bg-rose-500/15 px-2 py-0.5 rounded\">~$0.91</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 股价受财报后指引下调与股息暂停影响出现阶段性波动，市值约为 1.21 亿美元。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 2026 总营收</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$1.87B</span>\n <span class=\"text-xs font-bold text-rose-600 dark:text-rose-400 bg-rose-500/15 px-2 py-0.5 rounded\">-4.7% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 单季营收 $18.7 亿美元（按恒定汇率计 -4.5%），其中 Entry 及 Production 打印设备表现亮眼，抵消了部分中端设备下滑。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>Q3 调整后运营利润率</span>\n <span class=\"p-1.5 rounded-lg bg-xeroxblue-500/15 text-xeroxblue-600 dark:text-xeroxblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">6.6%</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+330 bps YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 调整后运营利润达 $1.24 亿美元，同比大幅增加 $5,900 万美元，展现出显著的成本削减成效。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>杠杆率与现金流指引</span>\n <span class=\"p-1.5 rounded-lg bg-xeroxred-500/15 text-xeroxred-600 dark:text-xeroxred-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">净杠杆 4.7x</span>\n <span class=\"text-xs font-bold text-xeroxred-700 dark:text-xeroxred-300 bg-xeroxred-500/15 px-2 py-0.5 rounded\">FCF 指引 $0.5-$1.0B</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 净债务与 TTM EBITDA 杠杆率降至 4.7x，全年自由现金流指引调整为 $5,000–$10,000 万美元。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务架构与Q3财报拆解 (Business Architecture & Q3 Earnings Breakdown)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-xeroxred-600 dark:text-xeroxred-400\">Section 01 · Business Architecture & Q3 Earnings Breakdown</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务架构与 Q3 财报拆解：打印设备分化、IT服务承压与成本优化</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q3 2026 总营收 $1.87B · 调整后运营利润 $124M</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2022–2026E 营收轨迹与调整后运营利润率演进</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">总营收处于温和收缩周期，但通过组织重组与成本控制，调整后运营利润率实现显著跃升</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_mix')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-xeroxred-600 dark:text-xeroxred-300 shadow-sm transition cursor-pointer\">视图A：营收板块结构</button>\n <button onclick=\"switchBizChart('segment_profit')\" id=\"btn-chart-seg\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：打印与IT方案拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">施乐核心业务板块与 Q3 表现</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-xeroxred-500/15 text-xeroxred-600 dark:text-xeroxred-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">打印及其他板块（Print and Other）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 营收 $16.88 亿美元（同比下降 2.9%）。其中入门级（Entry，+21%）与生产型打印（Production，+14%）设备销量增长强劲，有效对冲了中端（Mid-range）设备需求下滑。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-xeroxblue-500/15 text-xeroxblue-600 dark:text-xeroxblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">IT 解决方案板块（IT Solutions）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 营收 $1.87 亿美元（同比下降 17.3%），产品与服务收入均呈现阶段性回落，板块利润率为 4.4%，反映出销售组织调整与市场竞争加剧的阵痛。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">资本配置与债务优化行动</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 为应对现金流压力，公司果断暂停普通及优先股股息，并完成 $1.74 亿 2028 年到期高级票据的债务置换，全力压降 leverage。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">FY26 全年更新指引</span>\n <span class=\"font-bold text-xeroxred-600 dark:text-xeroxred-400\">营收 ~$7.6B · 调整后运营利润 $4.5–$4.75B · 自由现金流 $0.5–$1.0B</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-xeroxred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-xeroxred-500/15 text-xeroxred-700 dark:text-xeroxred-300 text-xs font-bold\">打印业务基石 · 占总营收 ~90%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">Print & Other Segment</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 打印及其他业务板块（Print and Other）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Q3 营收 $16.88 亿美元（同比下降 2.9%）。板块利润达到 $1.36 亿美元（同比大增 112.5%）。设备销售方面，Entry（+21%）与 Production（+14%）实现双位数强劲增长，并推出了三款全新生产型打印平台及达成与 Xeikon 的包装印刷战略合作。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>Q3 板块利润 $136M (+112.5% YoY)</span>\n <span class=\"text-xeroxred-600 dark:text-xeroxred-400 font-semibold\">Entry 与 Production 设备强劲反弹</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-xeroxblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-xeroxblue-500/15 text-xeroxblue-700 dark:text-xeroxblue-400 text-xs font-bold\">IT解决方案 · 转型阵痛期</span>\n <span class=\"font-mono text-xs font-bold text-xeroxblue-600 dark:text-xeroxblue-400\">IT Solutions Segment</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. IT 解决方案板块（IT Solutions）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n Q3 营收 $1.87 亿美元（同比下降 17.3%），其中产品销售下降 23%，服务下降 7%。板块利润为 $800 万美元（利润率 4.4%）。公司正在对其销售组织进行重组和投资，以期在未来恢复 IT 解决方案的规模化增长。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>Q3 营收 $187M (-17.3% YoY)</span>\n <span class=\"text-xeroxblue-600 dark:text-xeroxblue-400 font-semibold\">销售组织持续重组优化中</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与战略转型 (Industry Position & Strategic Transformation)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Strategic Transformation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与核心护城河：全球文档管理先驱、生产型印刷拓展与安全领导力</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：中等 (Moderate Moat · 传统办公打印与生产印刷先驱)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-xeroxred-500/15 text-xeroxred-600 dark:text-xeroxred-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球打印与文档管理技术先驱</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 施乐作为发明复印机的传奇企业，在企业级打印、文印管理及生产型印刷领域拥有深厚的技术积淀和庞大的全球客户粘性。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">生产印刷与包装赛道外延扩展</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 通过近期推出三款全新生产型打印平台及与 Xeikon（Flint Group）的战略合作，积极进军高增长的数字包装与标签印刷新市场。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-xeroxblue-500/15 text-xeroxblue-600 dark:text-xeroxblue-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Quocirca 打印安全与 IDC 评定领导者</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 在 Quocirca 2026 打印安全全景评估及 IDC MarketScape 全球邮件室解决方案中均被评为“领导者（Leader）”，彰显其企业级安全与自动化软实力。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">坚定执行“三大优先级”战略</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 围绕“稳定营收（Stabilize Revenue）、提升盈利（Increase Profitability）、降低杠杆（Reduce Leverage）”三大战略核心持续推进组织重组与成本优化。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">办公打印与数字化服务巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">施乐 (XRX) vs HP (HPQ) vs 佳能 (CAJ)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 办公与打印同行横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-xeroxred-600 dark:text-xeroxred-400\">Section 03 · Office & Print Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 办公与打印同行横向对比：重组转型期企业 vs 成熟硬件巨头</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-xeroxred-500 text-white shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('print')\" data-filter=\"print\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">传统打印与影像巨头</button>\n <button onclick=\"filterCompetitors('tech')\" data-filter=\"tech\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">个人与企业硬件同行</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与核心定位</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心主营业务</th>\n <th class=\"py-4 px-4 min-w-[140px]\">最新营收增速 (YoY)</th>\n <th class=\"py-4 px-4 min-w-[100px]\">盈利与现金状态</th>\n <th class=\"py-4 px-4 min-w-[115px]\">股息政策</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与竞合定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"print\" class=\"bg-xeroxred-500/5 dark:bg-xeroxred-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-xeroxred-600 text-white text-[10px] font-extrabold\">重组转型期</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">施乐 (XRX)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Xerox Holdings</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">企业级打印 + 生产印刷 + IT方案</td>\n <td class=\"py-4 px-4 font-mono font-bold text-rose-600 dark:text-rose-400\">-4.7% (Q3 营收)</td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">利润率改善 / 现金流承压</td>\n <td class=\"py-4 px-4 font-mono font-bold text-rose-600 dark:text-rose-400\">已宣布暂停股息</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>传统打印先驱与重组者：</strong>运营利润率翻倍至 6.6%，但面临营收收缩及债务杠杆优化挑战，全面聚焦现金保全。\n </td>\n </tr>\n\n <tr data-category=\"tech\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">惠普公司 (HPQ)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">HP Inc.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">个人电脑 PC + 消费及商用打印机</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">微增或平稳波动</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">现金流稳健</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~3.5%–4.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全球 PC 与打印巨头：</strong>拥有庞大的消费及中小企业终端硬件出货量，现金流回报稳定，体量与抗周期能力强于施乐。\n </td>\n </tr>\n\n <tr data-category=\"print\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">佳能 (CAJ)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Canon Inc.</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">影像设备 + 办公打印 + 半导体光刻</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">多元化业务支撑</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">财务结构稳健</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~2.5%–3.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>多元化影像与光学巨头：</strong>相机、医疗及半导体设备多元化布局有效分散了纯打印办公市场的萎缩风险。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球打印与硬件同行运营利润率与现金流状态对照</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">施乐 Q3 调整后运营利润率回升至 6.6%，但因现金流压力采取了暂停股息与债务重组等防御举措</p>\n </div>\n <span class=\"text-xs font-semibold text-xeroxred-700 dark:text-xeroxred-300 bg-xeroxred-500/15 px-2.5 py-1 rounded\">利润率改善但现金流承压</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与债务复利推演 (Financial Health & Debt Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Debt / Growth Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与债务优化体系：杠杆率降至 4.7x、自由现金流与债务再融资</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">净债务/EBITDA 4.7x · 现金及等价物 ~$530M</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-xeroxred-600 dark:text-xeroxred-400 uppercase\">Adjusted Operating Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">6.6%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n Q3 调整后运营利润率同比提升 330 个基点至 6.6%，成本协同与精简成效开始在利润端显现。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Cash & Equivalents</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$530M</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 截至 Q3 末持有现金及受限现金约 5.3 亿美元，流动性储备支持日常运营与短期债务腾挪。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-xeroxblue-600 dark:text-xeroxblue-400 uppercase\">Net Leverage Ratio</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">4.7x</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 净债务与 TTM EBITDA 杠杆率由上季度的 5.1x 持续下降至 4.7x，资本结构持续优化去杠杆。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Free Cash Flow Guidance</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$50–$100M</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 全年自由现金流指引调整为 5,000–10,000 万美元，反映出短期宏观与输入成本带来的现金流压力。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2021–2026E 总营收与调整后运营利润演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">顶线温和收缩但盈利质量改善，展示出施乐在重组转型期的利润修复弹性</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-xeroxred-700 dark:text-xeroxred-400 bg-xeroxred-500/15 px-2.5 py-1 rounded\">运营利润率持续回升</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-xeroxred-400 font-bold\">\n <span>XRX COMPOUNDING SIMULATOR · 施乐长期债务重组与估值推演器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">施乐长期持仓复利与债务优化动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 ~$0.91 | 全年自由现金流指引 ~$75M | 模拟成本削减与杠杆压降模型</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-xeroxred-500/15 border border-xeroxred-400/30 text-xs font-semibold text-xeroxred-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#EF4444] cursor-pointer\">\n <span>启用债务削减与利息节省优化模型</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始模拟投资额 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#EF4444] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">5 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"5\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#EF4444] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">运营利润与自由现金流年均复合增长率</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">8.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"0\" max=\"20\" step=\"0.5\" value=\"8.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">远期估值倍数预期（Forward P/E Multiple）：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(6)\" data-tax=\"6\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-xeroxred-400 transition cursor-pointer\">\n 6x 保守估值<br><span class=\"text-[10px] text-slate-400\">困境转折区间</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(10)\" data-tax=\"10\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-xeroxred-500 text-white border border-xeroxred-400 shadow transition cursor-pointer\">\n 10x 合理中枢<br><span class=\"text-[10px] text-slate-200\">成熟硬件中枢</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(14)\" data-tax=\"14\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-xeroxred-400 transition cursor-pointer\">\n 14x 牛市溢价<br><span class=\"text-[10px] text-slate-400\">重组成功溢价</span>\n </button>\n </div>\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计投资资产估值 (USD)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$44,040</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +46.8% (基于 10x 估值)</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计自由现金流总额</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-xeroxred-300 mt-1.5\">~$110M</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">现金流随成本压降逐步回升</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末对应估值多维年化回报率 (CAGR)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">8.0%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">年化复合投资回报增长</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末资产负债杠杆目标</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">&lt; 3.5x</div>\n <div class=\"text-shares-end text-xs text-slate-400 mt-1.5\">持续去杠杆并优化债务结构</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">利润率大幅提升 + 债务积极重组</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>运营利润率显著翻倍：</strong>Q3 调整后运营利润率飙升 330 bps 至 6.6%，协同效应与成本控制初见成效。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>果断的股东现金保全动作：</strong>主动宣布暂停普通及优先股股息，将宝贵现金流用于降低债务杠杆（净杠杆降至 4.7x）。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>债务再融资成功延期：</strong>完成 $1.74 亿 2028 年到期票据的置换，有效缓解短期债务到期兑付压力。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">顶线营收收缩 + 自由现金流下调</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>营收持续处于温和下滑区间：</strong>Q3 总营收同比下降 4.7% 至 $1.87B，中端打印设备需求疲软及 IT 解决方案下滑拖累顶线。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>自由现金流指引大幅下调：</strong>全 FCF 指引被下调至 $50–$100M，反映出输入成本与市场逆风带来的短期现金流压力。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>暂停分红影响投资者情绪：</strong>股息的暂停虽然保护了现金，但也对依赖红利回报的传统股东基础造成了一定心理冲击。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-xeroxred-600 dark:text-xeroxred-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景目标价推演与困境反转策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：特种困境反转仓位 · 审慎观察债务重组进展</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">10x–12x P/E ($1.50–$2.00)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>“三大优先级”成本节约超预期，IT 解决方案重组成功恢复增长；杠杆率加速降至 3.5x 以下，市场重估其现金保全与重组转型成效。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在年化总回报：+30% 至 +50%（高弹性困境反转）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-xeroxred-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-xeroxred-500/15 text-xeroxred-700 dark:text-xeroxred-300 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-xeroxred-600 dark:text-xeroxred-400\">概率：60%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">7x–9x P/E ($1.00–$1.25)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>营收维持 4% 左右温和收缩，但调整后运营利润率稳定在 6%–7% 区间；自由现金流达成 $50–$100M 指引，债务平稳过渡。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-xeroxred-600 dark:text-xeroxred-400\">\n 稳健年化总回报：+10% 至 +15%（重组过渡期收益）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">4x–5x P/E ($0.50–$0.70)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>输入成本通胀加剧且 IT 服务复苏受阻，导致自由现金流跌破指引，债务杠杆优化不及预期，估值持续受到压制。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在回撤风险：-20% 至 -30%（债务与现金流压力考验底线）\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 传统打印硬件需求结构性萎缩</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">无纸化办公对文印后市场（Post-sale）的长期冲击</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管入门级设备表现亮眼，但中端打印设备及耗材/外包服务收入长期面临无纸化办公趋势的结构性压降。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 债务杠杆率与流动性风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">4.7x 净杠杆率与后续债务到期兑付</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 尽管完成了 2028 年票据的置换，但整体 4.7x 的净债务杠杆仍需持续通过自由现金流和资产出售进行压降。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-xeroxblue-500/10 text-xeroxblue-600 dark:text-xeroxblue-400 text-xs font-bold\">03 · IT 解决方案业务转型阵痛</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">IT 解决方案营收连续下滑 (-17.3% YoY)</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 板块销售组织重组的成效滞后，亟需恢复产品与服务的正向增长轨道以贡献毛利增量。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 宏观输入成本与供应链通胀</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">原材料与供应链运费波动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 输入成本上升直接压制了全年的自由现金流预期，需密切关注成本传导与价格调整的落地效率。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-xeroxred-300 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与困境反转策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 特种困境反转小仓位配置</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 将 XRX 定位为受益于成本重组、利润率翻倍但伴随债务考验的事件驱动型困境反转标的，建议控制仓位。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-xeroxred-300 mb-1\">2. 密切跟踪现金流与杠杆指标</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 重点监测每季度自由现金流达成情况（$50M–$100M 指引）及净债务杠杆率能否持续向 3.5x 迈进。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 暂停分红后的现金保全视角</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 尽管股息暂停短期内对收益型投资者不利，但从保护企业偿债能力和度过转型阵痛来看，是务实且必要的资本决策。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-xeroxred-500/15 text-xeroxred-700 dark:text-xeroxred-300 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验施乐利润率改善与债务重组进展：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 调整后运营利润率是否稳守 6%+ 目标（如 Q3 达到 6.6%）</span>\n <span class=\"text-[11px] font-mono text-xeroxred-600 dark:text-xeroxred-400 font-semibold shrink-0\">盈利改善指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查每季财报运营利润率是否维持在 6%–7% 区间，确认成本削减成效持续落地。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 全年自由现金流是否达成 $5,000–$10,000 万美元指引</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">现金流安全防线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪每季度自由现金流生成情况，确保满足 $50M–$100M 的全年更新指引。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 净债务杠杆率（Net Leverage）持续向 3.5x–4.0x 迈进</span>\n <span class=\"text-[11px] font-mono text-xeroxblue-600 dark:text-xeroxblue-400 font-semibold shrink-0\">债务压降指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控净债务与 TTM EBITDA 杠杆率（当前 4.7x）的下降趋势，评估债务优化成果。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 打印设备销售（Entry 及 Production）双位数增长势头</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">核心硬件动能</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪入门级与生产型打印设备的安装量与设备收入，评估新产品及包装印刷合作拓展成效。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. IT 解决方案板块销售组织重组后的营收企稳回升</span>\n <span class=\"text-[11px] font-mono text-xeroxblue-600 dark:text-xeroxblue-400 font-semibold shrink-0\">业务多元化转型</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估 IT 服务营收下滑趋势是否收窄并恢复正向增长，检验销售团队重组效果。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#EF4444]\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 债务再融资与债券置换（如延长 2028 到期债务）执行进展</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">资本结构优化</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控后续资本市场债务到期日的管理动作，确保没有流动性断档风险。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>施乐 Xerox Holdings Corporation (NASDAQ: XRX) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：2026Q3 财报 (SEC Form 10-Q) 及 2026 年 11 月市场一致预期 (FY26E)</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于施乐公开财务报告（10-Q/10-K）、2026Q3 财报业绩公告及全球办公打印行业调研资料整理生成，旨在提供结构化的产业分析与重组企业估值框架。报告中涉及的盈利预测、现金流指引、三情景目标价及复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-xeroxred-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-xeroxred-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-xeroxred-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-xeroxred-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'print' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n let currentMultiple = 10;\n\n function setTaxRate(mult) {\n currentMultiple = mult;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnMult = parseFloat(btn.dataset.tax);\n if (Math.abs(btnMult - mult) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-xeroxred-500 text-white border border-xeroxred-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-200';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-xeroxred-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initEps = 0.10; // proxy for normalized EPS during turnaround\n const g = growthPct / 100;\n\n let finalEps = initEps * Math.pow(1 + g, years);\n let estimatedStockPrice = finalEps * currentMultiple;\n let initialStockPrice = 0.91;\n let totalReturnPct = ((estimatedStockPrice - initialStockPrice) / initialStockPrice) * 100;\n let finalPortfolioVal = principal * (1 + totalReturnPct / 100);\n let cagr = (Math.pow(finalPortfolioVal / principal, 1 / years) - 1) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (基于 ${currentMultiple}x P/E)`;\n document.getElementById('sim-annual-div').textContent = '~$' + (75 + years * 10).toFixed(0) + 'M';\n document.getElementById('sim-yoc').textContent = cagr.toFixed(1) + '%';\n document.getElementById('sim-cum-div').textContent = `< 3.5x`;\n }\n\n const KPI_STORAGE_KEY = 'xrx_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_mix';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const revConfig = {\n type: 'bar',\n data: {\n labels: ['2022', '2023', '2024', '2025', '2026Q3'],\n datasets: [\n {\n label: '打印及其他业务营收 ($B)',\n data: [6.8, 6.7, 6.6, 6.9, 1.69],\n backgroundColor: '#EF4444',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n label: 'IT解决方案营收 ($B)',\n data: [0.3, 0.8, 0.9, 0.9, 0.19],\n backgroundColor: '#3B82F6',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n type: 'line',\n label: '调整后运营利润率 (%)',\n data: [4.5, 5.0, 5.2, 5.5, 6.6],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y1' ? `运营利润率: ${ctx.parsed.y}%` : `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 10,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 10,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11 }, callback: v => v + '%' }\n }\n }\n }\n };\n\n const segConfig = {\n type: 'bar',\n data: {\n labels: [\n '打印及其他板块利润 ($M)',\n 'IT解决方案板块利润 ($M)',\n '调整后运营利润率 (%)',\n '净债务杠杆率 (倍)'\n ],\n datasets: [\n {\n label: 'Q3 2026 核心财务指标',\n data: [136, 8, 6.6, 4.7],\n backgroundColor: [\n '#EF4444',\n '#3B82F6',\n '#10B981',\n '#6366F1'\n ],\n borderRadius: 6,\n barThickness: 26\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `指标数值: ${ctx.parsed.x}${ctx.dataIndex < 2 ? 'M' : (ctx.dataIndex === 2 ? '%' : 'x')}`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 160,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 } }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_mix' ? revConfig : segConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSeg = document.getElementById('btn-chart-seg');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_mix') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-xeroxred-600 dark:text-xeroxred-300 shadow-sm transition cursor-pointer';\n btnSeg.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2022–2026E 营收轨迹与调整后运营利润率演进';\n subEl.textContent = '总营收处于温和收缩周期，但通过组织重组与成本控制，调整后运营利润率实现显著跃升';\n } else {\n btnSeg.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-xeroxred-600 dark:text-xeroxred-300 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q3 核心板块利润与杠杆指标拆解';\n subEl.textContent = '打印板块利润大增至 $136M，IT解决方案利润 $8M，净杠杆率降至 4.7x';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '打印与文档管理技术底蕴',\n '生产印刷与包装外延扩展',\n '打印安全与自动化行业认证',\n '成本精简与运营利润弹性',\n '债务重组与现金流保全执行力'\n ],\n datasets: [\n {\n label: '施乐 (XRX)',\n data: [9.2, 8.0, 9.0, 8.5, 7.8],\n borderColor: '#EF4444',\n backgroundColor: 'rgba(239, 68, 68, 0.24)',\n pointBackgroundColor: '#EF4444',\n borderWidth: 2.5\n },\n {\n label: '惠普公司 (HPQ)',\n data: [9.5, 7.0, 8.5, 8.8, 9.2],\n borderColor: '#3B82F6',\n backgroundColor: 'rgba(59, 130, 246, 0.14)',\n pointBackgroundColor: '#3B82F6',\n borderWidth: 2.0\n },\n {\n label: '佳能 (CAJ)',\n data: [9.0, 8.2, 8.0, 8.2, 8.5],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.12)',\n pointBackgroundColor: '#10B981',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '施乐 (XRX · 重组转型期)',\n '惠普公司 (HPQ · 硬件巨头)',\n '佳能 (CAJ · 多元化影像巨头)'\n ],\n datasets: [\n {\n label: '运营利润率 / 利润表现 (%)',\n data: [6.6, 8.0, 7.5],\n backgroundColor: '#EF4444',\n borderRadius: 5,\n barThickness: 18\n },\n {\n label: '远期股息率 Dividend Yield (%)',\n data: [0.0, 3.75, 2.75],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 18\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 12,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2021', '2022', '2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '全年总营收 ($ 亿美元)',\n data: [7.1, 7.1, 6.9, 6.7, 7.1, 7.6],\n backgroundColor: 'rgba(239, 68, 68, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '调整后运营利润 ($ 亿美元)',\n data: [0.45, 0.35, 0.40, 0.42, 0.38, 0.46],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 10,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '总营收 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 1,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '调整后运营利润 ($B)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>\n"};
